"""Inspected passages, bounded paraphrases, source origins and retrieval limitations."""
ASOF = '2026-10-28'
sources, retrievals = [], []
def src(n,title,author,url,date,kind,locator,passage,note='',status='Passage inspected',origin=None):
    sid=f'S{n:03d}'
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'Publication date':date,'URL':url,'Access date':ASOF,'Source class':kind,'Primary / secondary':'Primary' if kind in ('Official record','Court record','Legislation','Primary statement','Official election return') else 'Secondary','Access status':status,'Origin ID':origin or sid,'Locator':locator,'Reliability / limitation':note or 'Supports the specified passage and period; personal causation and later outcomes require separate evidence.'})
    retrievals.append({'id':f'R{n:03d}','source_id':sid,'url_or_query':url,'access_date':ASOF,'route':'Canonical page or identified institutional/reporter reproduction','access_status':status,'origin_id':origin or sid,'locator':locator,'passage_paraphrase':passage,'method':'web.run passage inspection','result':'Relevant passage inspected' if status=='Passage inspected' else note,'next_action':'Use only for inspected claims; pursue gaps through the Research Queue.'})

